pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item_fraction = (item_size as f64 / capacity).clamp(0.0, 1.0);
    let post_fraction = (post_residual as f64 / capacity).clamp(0.0, 1.0);
    let mean_fraction = (mean_residual / capacity).clamp(0.0, 1.0);
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    // Reward bins that become structurally tight after placement.
    let tightness = (1.0 - post_fraction).max(0.0);
    let fit_quality = (1.0 - (post_residual as f64 / bin_residual.max(1) as f64)).clamp(0.0, 1.0);
    let mut score = 112.0 * tightness.powi(2) + 9.0 * fit_quality;

    // Avoid concentrating items in bins whose residual is unusually large.
    let relative_residual = post_fraction - mean_fraction;
    score += 13.0 * relative_residual.abs();
    score += 7.0 * item_fraction * (1.0 - post_fraction);

    // Preserve exact-fit and near-exact-fit opportunities, but only mildly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= item_size / 8 {
        score -= 9.0;
    }

    // Use the next item as a coupled residual-consumption signal.
    if next_item_size > 0 {
        let next_fraction = (next_item_size as f64 / capacity).clamp(0.0, 1.0);
        let residual_window = (post_fraction / next_fraction.max(0.01)).min(4.0);
        score -= 5.5 * (1.0 - residual_window / 4.0) * (0.45 + 0.55 * progress);

        if post_residual >= next_item_size && post_residual <= 2 * next_item_size {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // As the stream winds down, favor closing fragmented bins.
    let endgame = progress.powi(3);
    score -= 15.0 * endgame * tightness;
    score -= 4.0 * (1.0 - progress) * tightness;

    // A final fitting candidate has significant option value if its residual can
    // be retained for an upcoming item.
    if fitting_bins_count <= 1 && next_item_size > 0 {
        let next_fraction = (next_item_size as f64 / capacity).clamp(0.0, 1.0);
        let consumes_next = (post_fraction / next_fraction.max(0.01)).min(1.0);
        score -= 11.0 * consumes_next * (0.55 + 0.45 * progress);
    }

