    // rises when many bins exist or when the current item is large.
    if bin_residual == bin_capacity {
        let inventory_pressure = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score += 31.0 + 13.0 * (1.0 - progress) + 5.0 * inventory_pressure;
        score += 8.0 * item_fraction;

        if fitting_bins_count > 1 {
            score += 4.0 * fitting_bins_count as f64;
        }
    }

    score
}
